import{_ as a,o as t,c as i,ae as s}from"./chunks/framework.VfpTXP3k.js";const p=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Chinese ID number validation — the X check digit, 15 to 18 digit conversion, algorithm details and privacy","frontmatter":{"title":"FAQ","description":"Frequently asked questions about Chinese ID number validation — the X check digit, 15 to 18 digit conversion, algorithm details and privacy"},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md","lastUpdated":1785199646000}'),o={name:"en/guide/faq.md"};function r(n,e,d,l,h,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="what-does-the-x-at-the-end-of-an-id-number-mean" tabindex="-1">What does the X at the end of an ID number mean? <a class="header-anchor" href="#what-does-the-x-at-the-end-of-an-id-number-mean" aria-label="Permalink to &quot;What does the X at the end of an ID number mean?&quot;">​</a></h2><p>X is one of the 11 possible check digit values. The check digit is computed from the first 17 digits using the ISO 7064:1983 MOD 11-2 weighted algorithm, yielding 0–10. When the result is 10, the Roman numeral <strong>X</strong> is used to keep the total length at 18 digits.</p><p>This library compares check digits case-insensitively, so a lowercase <code>x</code> is also accepted:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isValid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;37012519790112881x&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → true (lowercase x works too)</span></span></code></pre></div><h2 id="what-s-the-difference-between-15-digit-and-18-digit-ids" tabindex="-1">What&#39;s the difference between 15-digit and 18-digit IDs? <a class="header-anchor" href="#what-s-the-difference-between-15-digit-and-18-digit-ids" aria-label="Permalink to &quot;What&#39;s the difference between 15-digit and 18-digit IDs?&quot;">​</a></h2><p>The 15-digit format is the legacy version issued before 1999; the 18-digit format is defined by GB 11643-1999. Two differences:</p><ol><li><strong>Birth year</strong>: 15-digit uses a 2-digit year (<code>YYMMDD</code>, assumed 19xx); 18-digit uses the full 4-digit year (<code>YYYYMMDD</code>)</li><li><strong>Check digit</strong>: 15-digit has none; the 18-digit format ends with a weighted check digit</li></ol><p><code>toEighteen()</code> upgrades per the standard: prepends <code>19</code> to the year and appends the computed check digit:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">toEighteen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;110101900101001&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → &#39;110101199001011001&#39;</span></span></code></pre></div><h2 id="does-a-passing-validation-mean-the-id-number-actually-exists" tabindex="-1">Does a passing validation mean the ID number actually exists? <a class="header-anchor" href="#does-a-passing-validation-mean-the-id-number-actually-exists" aria-label="Permalink to &quot;Does a passing validation mean the ID number actually exists?&quot;">​</a></h2><p><strong>No.</strong> This library performs <strong>offline format validation</strong> only:</p><ul><li>Length and character rules (<code>checkBaseFormat</code>)</li><li>Province administrative code validity (<code>checkProvince</code>)</li><li>Birth date legality (including leap years)</li><li>Check digit consistency (MOD 11-2)</li></ul><p>A &quot;valid&quot; result only means the number <strong>follows the encoding rules</strong> — it cannot confirm the number was actually issued or belongs to a real person. Real-name verification requires official channels; no client-side library can do that.</p><h2 id="are-hong-kong-macao-and-taiwan-codes-supported" tabindex="-1">Are Hong Kong, Macao and Taiwan codes supported? <a class="header-anchor" href="#are-hong-kong-macao-and-taiwan-codes-supported" aria-label="Permalink to &quot;Are Hong Kong, Macao and Taiwan codes supported?&quot;">​</a></h2><p>Yes. The first two address digits are validated against GB/T 2260 extended codes:</p><table tabindex="0"><thead><tr><th>Code</th><th>Region</th></tr></thead><tbody><tr><td><code>71</code></td><td>Taiwan Province</td></tr><tr><td><code>81</code></td><td>Hong Kong SAR</td></tr><tr><td><code>82</code></td><td>Macao SAR</td></tr></tbody></table><h2 id="what-are-the-birth-date-validation-rules" tabindex="-1">What are the birth date validation rules? <a class="header-anchor" href="#what-are-the-birth-date-validation-rules" aria-label="Permalink to &quot;What are the birth date validation rules?&quot;">​</a></h2><p>Strictly per the Gregorian calendar:</p><ul><li>Month must be between 1 and 12</li><li>Day must not exceed the actual days in that month (30 for Apr/Jun/Sep/Nov, 31 otherwise)</li><li><strong>February follows leap-year rules</strong>: 29 days in leap years, 28 otherwise (divisible by 4 but not 100, or divisible by 400)</li></ul><p>So <code>20000229</code> (2000 was a leap year) is legal, while <code>19000229</code> (1900 was not) is rejected.</p><h2 id="how-is-the-age-returned-by-parse-calculated" tabindex="-1">How is the age returned by parse() calculated? <a class="header-anchor" href="#how-is-the-age-returned-by-parse-calculated" aria-label="Permalink to &quot;How is the age returned by parse() calculated?&quot;">​</a></h2><p>As full years (周岁): current year minus birth year, minus 1 if this year&#39;s birthday hasn&#39;t passed yet.</p><p>Note that age is a <strong>dynamic value at call time</strong> — calling on different dates may return different results.</p><h2 id="will-my-id-number-be-uploaded-anywhere" tabindex="-1">Will my ID number be uploaded anywhere? <a class="header-anchor" href="#will-my-id-number-be-uploaded-anywhere" aria-label="Permalink to &quot;Will my ID number be uploaded anywhere?&quot;">​</a></h2><p><strong>No.</strong> This library makes zero network requests. All computation (including the <a href="/china-id-card/en/playground.html">Playground</a>) happens locally in your browser. The library has no dependencies — you can audit every line of the <a href="https://github.com/tonyc726/china-id-card" target="_blank" rel="noreferrer">source code</a>.</p><h2 id="typescript-import-errors" tabindex="-1">TypeScript import errors? <a class="header-anchor" href="#typescript-import-errors" aria-label="Permalink to &quot;TypeScript import errors?&quot;">​</a></h2><p>The library ships its own type declarations (<code>dist/index.d.ts</code>) — no <code>@types/*</code> package needed. If you hit issues, check that:</p><ol><li><code>tsconfig.json</code> uses <code>moduleResolution: &quot;bundler&quot;</code> (or <code>node16</code>/<code>nodenext</code>)</li><li>You import as an ES module: <code>import { isValid } from &#39;china-id-card&#39;</code></li></ol><h2 id="more-questions" tabindex="-1">More questions? <a class="header-anchor" href="#more-questions" aria-label="Permalink to &quot;More questions?&quot;">​</a></h2><p>Ask on <a href="https://github.com/tonyc726/china-id-card/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p>',31)])])}const g=a(o,[["render",r]]);export{p as __pageData,g as default};
